demos.db_schema:
DATABASE SCHEMA:

Table: Fact_Player_Performance_Weekly
Columns: {"season_id": "The unique primary key for a fantasy season, representing the calendar year.", "game_week": "The week of the NFL season for this stat line.", "player_name": "The full name of the NFL player.", "player_position": "The position of the player.", "owner_name": "The display name of the fantasy owner.", "fantasy_team_name": "The name of the fantasy team for that season.", "is_starting": "Indicates if the player was in a starting lineup position.", "total_fantasy_points": "The player's total fantasy points for this specific week.", "pass_yds": "Total passing yards for the week.", "pass_tds": "Total passing touchdowns for the week.", "rush_yds": "Total rushing yards for the week.", "rush_tds": "Total rushing touchdowns for the week.", "rec_yds": "Total receiving yards for the week.", "rec_tds": "Total receiving touchdowns for the week."}

Table: Fact_Player_Season_Stat_Leaders
Columns: {"season_id": "The season year (e.g., 2022).", "player_name": "The full name of the player.", "player_position": "The position of the player.", "games_played": "Number of games played in that season.", "total_fantasy_points": "The player's total fantasy points for the entire season.", "season_rank": "The player's final rank among all players at their position for the season."}

Table: Fact_Matchup_History_Wide
Columns: {"season_id": "The season year the matchup took place.", "nfl_week": "The week of the NFL season.", "fantasy_week": "The name or number of the fantasy week.", "matchup_category": "Category: 'Regular Season', 'Postseason (Non-playoff)', or 'Playoff'.", "manager_name": "The name of the primary manager for this row.", "manager_team": "The name of the manager's fantasy team.", "manager_score": "The final fantasy point total for the manager.", "opponent_name": "The name of the opponent manager.", "opponent_team": "The name of the opponent's team.", "opponent_score": "The final fantasy point total for the opponent.", "margin_of_victory": "The absolute point difference between the two scores.", "outcome": "The result for the manager: 'Win', 'Loss', or 'Tie'."}

Table: Fact_Draft_Performance_Analysis
Columns: {"season_id": "The season year of the draft.", "player_name": "The name of the drafted player.", "owner_name": "The name of the owner who made the pick.", "pick_overall": "The overall pick number in the entire draft.", "draft_value_vs_adp": "Indicates how much of a 'reach' or 'steal' the pick was compared to market ADP.", "total_season_points": "Total fantasy points the player scored during that entire season.", "points_scored_over_expected": "Difference between actual points and expected points from that draft slot.", "finish_rank": "The player's final rank among all players at their position.", "draft_rank": "The rank of the player at their position when drafted.", "rank_diff": "Difference between draft rank and final finish rank."}

Table: Fact_Team_Season_Standings
Columns: {"season_id": "The season year.", "owner_name": "The name of the team's owner.", "regular_season_wins": "Number of wins during the regular season only.", "final_standing": "The team's final rank including playoffs.", "is_champion": "Indicates if the team won the championship."}

Table: Fact_Manager_Career_Leaderboard
Columns: {"owner_name": "The display name of the fantasy owner.", "career_wins": "Total wins including regular season and playoffs.", "career_win_percentage": "The owner's career winning percentage.", "championships_won": "The total number of championships won.", "career_points_for": "Total career fantasy points scored.", "career_playoff_rate": "Percentage of seasons where manager qualified for playoffs.", "avg_final_standing": "The owner's average final ranking."}

Table: Fact_Player_Master_Profile
Columns: {"player_name": "The full name of the player.", "primary_position": "The main position the player has played.", "career_games_played": "Total number of games played over their career.", "career_fantasy_points": "Total career fantasy points scored.", "total_seasons_active": "Number of seasons the player has been active."}

Table: Players_Wide
Columns: {"player_id": "The unique primary key for an individual player.", "player_name": "The full name of the player."}

